def process(variableDescrip) -> pd.DataFrame:
    import pandas as pd

    df = variableDescrip.copy()
    df.columns = [c.strip() for c in df.columns]

    def norm(s):
        if pd.isna(s):
            return ''
        return str(s).lower()

    df['var'] = df['Variable Name'].astype(str).str.strip()
    df['desc_young'] = df['Young et al. 2020, Table 1'].map(norm)
    df['desc_alt'] = df['Alternative description'].map(norm)
    df['desc'] = (df['desc_young'].fillna('') + ' ' + df['desc_alt'].fillna('')).str.strip()

    # look for relevant keywords
    pattern = r'(residential|residence|home|house|housing|structure|building|destroy|damage|damaged|loss)'
    cand = df[df['desc'].str.contains(pattern, regex=True, na=False)].copy()

    # score for residential houses damaged vs threatened
    def score(text):
        s = 0
        if any(k in text for k in ['residential', 'home', 'house', 'housing']):
            s += 3
        if any(k in text for k in ['damage', 'damaged', 'destroy', 'loss']):
            s += 2
        if 'threat' in text or 'threaten' in text:
            s -= 2
        if 'commercial' in text or 'comm ' in text or 'comm_' in text:
            s -= 1
        return s

    cand['score'] = cand['desc'].map(score)
    cand = cand.sort_values(['score', 'var'], ascending=[False, True])

    return cand[['var','score','desc_young','desc_alt']].reset_index(drop=True)
